import java.util.*;import forge.util.MyRandom;
public final class VerifyCoinRandom {
 static List<Object> sample(Random r){MyRandom.setRandom(r);Random x=MyRandom.getRandom();List<Object> values=new ArrayList<>();for(int i=0;i<100;i++){values.add(x.nextInt());values.add(x.nextInt(37));values.add(x.nextBoolean());values.add(x.nextLong());values.add(Double.doubleToLongBits(x.nextDouble()));values.add(Float.floatToIntBits(x.nextFloat()));values.add(Double.doubleToLongBits(x.nextGaussian()));byte[] b=new byte[11];x.nextBytes(b);values.add(Arrays.toString(b));values.add(x.ints(7,-10,10).sum());}return values;}
 public static void main(String[] args){long c=MyRandom.callCount();var old=sample(new Random(7274));long a=MyRandom.callCount()-c;c=MyRandom.callCount();var observed=sample(new ForgeLandEngine.CoinRandom(7274));long b=MyRandom.callCount()-c;if(!old.equals(observed)||a!=b||!ForgeLandEngine.physicalCoinTosses.get().isEmpty())throw new AssertionError("Random sequence/count or non-coin observation changed");if(!(new ForgeLandEngine.CoinSecureRandom() instanceof java.security.SecureRandom))throw new AssertionError();System.out.println("PASS "+old.size()+" mixed random results and "+a+" native random calls unchanged; no false coin captures");}
}
